content.text:
{
  "name": "Pylontech RS485 通信协议组件",
  "name_en": "Pylontech RS485 Protocol Component",
  "manufacturer": "",
  "description": "这是一个非实体的通信协议组件，用于通过 USB 转 RS-485 串口适配器与 Pylontech 协议设备进行报文收发。它负责数据包的前后缀处理、校验和计算与校验、接收超时处理，以及串口连接与接收缓冲区管理，适合在实验系统中作为底层串口通信辅助模块使用。",
  "description_en": "This is a non-physical communication/protocol component for sending and receiving packets to Pylontech-protocol devices through a USB-to-RS485 serial adapter. It handles packet prefix/suffix framing, checksum calculation and validation, receive timeouts, and serial connection and RX buffer management, making it suitable as a low-level serial communication helper in laboratory systems.",
  "actions": [
    {
      "action_name": "auto-verbose",
      "description": "设置通信组件的详细输出级别。",
      "description_en": "Set the verbosity level of the communication component."
    },
    {
      "action_name": "auto-receive",
      "description": "从 RS-485 串口接收一个 Pylontech 协议数据包，并检查长度、前后缀和校验和。",
      "description_en": "Receive one Pylontech-protocol packet from the RS-485 serial port and check its length, framing bytes, and checksum."
    },
    {
      "action_name": "auto-get_chk_sum",
      "description": "计算给定数据的校验和。",
      "description_en": "Calculate the checksum for the given data."
    },
    {
      "action_name": "auto-send",
      "description": "向 RS-485 串口发送一个 Pylontech 协议数据包，并自动补充前后缀与校验和。",
      "description_en": "Send one Pylontech-protocol packet over the RS-485 serial port, automatically adding framing bytes and checksum."
    },
    {
      "action_name": "auto-clear_rx_buffer",
      "description": "清空串口接收缓冲区中的待处理数据。",
      "description_en": "Clear pending data from the serial receive buffer."
    },
    {
      "action_name": "auto-reconnect",
      "description": "强制重新连接串口。",
      "description_en": "Force reconnection to the serial port."
    },
    {
      "action_name": "auto-close",
      "description": "关闭串口连接。",
      "description_en": "Close the serial connection."
    }
  ],
  "tag_hints": [
    "RS-485 serial communication",
    "USB-to-RS485 adapter",
    "packet framing",
    "checksum validation",
    "serial port reconnect",
    "Pylontech protocol",
    "RX buffer management"
  ]
}

